#!/usr/bin/env python3
# /// script
# requires-python = ">=3.11"
# dependencies = ["tiktoken"]
# ///
"""count_tokens: the one length metric for skill authoring.

Counts tokens with tiktoken's cl100k_base encoding. When tiktoken is not
installed it falls back to len(text) // 4 and says so, so the script runs
under a bare interpreter too.

Usage:
  count_tokens.py <path> [<path> ...]   files, or directories recursed for text files
  count_tokens.py --stdin               count the text read from stdin

Output, one JSON object on stdout:
  {"files": [{"path": str, "tokens": int}, ...], "total": int, "method": "tiktoken" | "fallback"}
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ENCODING = "cl100k_base"
TEXT_SUFFIXES = {".md", ".py", ".toml", ".yaml", ".yml", ".json", ".txt", ".csv", ".html", ".sh", ".cfg", ".ini"}
SKIP_DIRS = {".git", "__pycache__", ".pytest_cache", "node_modules", ".venv", "venv"}


def count_tokens(text: str) -> tuple[int, str]:
    """Return (token_count, method); method is "fallback" when tiktoken is unavailable."""
    try:
        import tiktoken
    except Exception:
        return len(text) // 4, "fallback"
    try:
        enc = tiktoken.get_encoding(ENCODING)
    except Exception:
        return len(text) // 4, "fallback"
    return len(enc.encode(text)), "tiktoken"


def iter_text_files(root: Path):
    """Yield text files under root, skipping noise directories and hidden files."""
    # Sorted by the posix string so the order is the same on every OS; Path sorts case-insensitively on Windows.
    for path in sorted(root.rglob("*"), key=lambda p: p.relative_to(root).as_posix()):
        if not path.is_file():
            continue
        parts = path.relative_to(root).parts
        if any(part in SKIP_DIRS or part.startswith(".") for part in parts):
            continue
        if path.suffix.lower() in TEXT_SUFFIXES:
            yield path


def read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return path.read_text(encoding="utf-8", errors="replace")


def count_paths(paths: list[Path]) -> dict:
    files = []
    method = "tiktoken"
    for given in paths:
        targets = list(iter_text_files(given)) if given.is_dir() else [given]
        for target in targets:
            tokens, used = count_tokens(read_text(target))
            if used == "fallback":
                method = "fallback"
            files.append({"path": str(target), "tokens": tokens})
    return {"files": files, "total": sum(f["tokens"] for f in files), "method": method}


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("paths", nargs="*", type=Path, help="files or directories to count")
    p.add_argument("--stdin", action="store_true", help="read text from stdin instead of paths")
    args = p.parse_args(argv)

    if args.stdin and args.paths:
        p.error("provide paths or --stdin, not both")
    if not args.stdin and not args.paths:
        p.error("provide at least one path or --stdin")

    if args.stdin:
        tokens, method = count_tokens(sys.stdin.read())
        result = {"files": [{"path": "<stdin>", "tokens": tokens}], "total": tokens, "method": method}
    else:
        missing = [str(path) for path in args.paths if not path.exists()]
        if missing:
            p.error(f"not found: {', '.join(missing)}")
        result = count_paths(args.paths)

    print(json.dumps(result))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# /// script
# requires-python = ">=3.11"
# ///
"""cut_check: what a rewrite dropped that must survive character for character.

Compares each prompt file (the .md files outside scripts/, and the root customize.toml) in a copy of the
skill taken before the rewrite with the same file after it. Judging whether a rule survived is the
Checker's work; this catches only what a string comparison can.

Usage:
  cut_check.py <before-folder> <after-folder> [--protect <path>[#<heading>] ...]

Output, one JSON object on stdout:
  {"files": [{"path", "missing", "lost": [str]}], "missing": [path], "lost": [path]}
A file's lost lists each Jinja construct ({{ }} or {% %}) and {skill-root} or {project-root} path that is
gone, "frontmatter" when the frontmatter changed, and "protected" or "protected: <heading>" for a
--protect file or section no longer kept word for word. Top-level missing and lost list the files with any.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from collections import Counter
from pathlib import Path

FRONTMATTER_RE = re.compile(r"\A---\n.*?\n---\n", re.DOTALL)
HEADING_RE = re.compile(r"^(#{1,6})\s+(.+?)\s*#*\s*$", re.MULTILINE)
JINJA_RE = re.compile(r"\{\{.*?\}\}|\{%.*?%\}", re.DOTALL)
ROOT_PATH_RE = re.compile(r"\{(?:skill-root|project-root)\}[^\s`'\"()<>\[\],;]*")
SKIP_DIRS = {".git", "__pycache__", ".pytest_cache", "node_modules", ".venv", "venv"}


def prompt_files(root: Path) -> list[str]:
    out = []
    for path in sorted(root.rglob("*")):
        rel = path.relative_to(root)
        if not path.is_file() or SKIP_DIRS & set(rel.parts):
            continue
        if (path.suffix == ".md" and rel.parts[0] != "scripts") or rel == Path("customize.toml"):
            out.append(rel.as_posix())
    # Path order folds case on Windows; strings sort the same on every OS.
    return sorted(out)


def section(text: str, heading: str) -> str | None:
    """The heading line and everything under it up to the next heading of the same or a higher level."""
    for match in HEADING_RE.finditer(text):
        if match.group(2) == heading:
            level = len(match.group(1))
            for nxt in HEADING_RE.finditer(text, match.end()):
                if len(nxt.group(1)) <= level:
                    return text[match.start() : nxt.start()]
            return text[match.start() :]
    return None


def lost_in(before: str, after: str, protects: list[str | None]) -> list[str]:
    jinja = Counter(" ".join(m.split()) for m in JINJA_RE.findall(before))
    jinja -= Counter(" ".join(m.split()) for m in JINJA_RE.findall(after))
    lost = list(jinja.elements())
    after_paths = {p.rstrip(".:") for p in ROOT_PATH_RE.findall(after)}
    lost += sorted({p.rstrip(".:") for p in ROOT_PATH_RE.findall(before)} - after_paths)
    fm_before, fm_after = FRONTMATTER_RE.match(before), FRONTMATTER_RE.match(after)
    if fm_before and (not fm_after or fm_before.group(0) != fm_after.group(0)):
        lost.append("frontmatter")
    for heading in protects:
        if heading is None:
            if before != after:
                lost.append("protected")
        else:
            kept = section(before, heading)
            if kept is None:
                raise ValueError(f"--protect section not found: #{heading}")
            if kept not in after:
                lost.append(f"protected: {heading}")
    return lost


def check(before: Path, after: Path, protect: list[str]) -> dict:
    files = prompt_files(before)
    protects: dict[str, list[str | None]] = {}
    for entry in protect:
        path, _, heading = entry.partition("#")
        if path not in files:
            raise ValueError(f"--protect matches no prompt file: {entry}")
        protects.setdefault(path, []).append(heading.strip() or None)

    out = []
    for rel in files:
        target = after / rel
        missing = not target.is_file()
        lost = []
        if not missing:
            old = (before / rel).read_text(encoding="utf-8")
            lost = lost_in(old, target.read_text(encoding="utf-8"), protects.get(rel, []))
        out.append({"path": rel, "missing": missing, "lost": lost})
    return {
        "files": out,
        "missing": [f["path"] for f in out if f["missing"]],
        "lost": [f["path"] for f in out if f["lost"]],
    }


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("before", type=Path, help="copy of the skill folder taken before the rewrite")
    p.add_argument("after", type=Path, help="the skill folder now")
    p.add_argument("--protect", action="append", default=[], help="file, or file#heading, relative to the skill")
    args = p.parse_args(argv)
    for folder in (args.before, args.after):
        if not folder.is_dir():
            p.error(f"not a directory: {folder}")
    try:
        result = check(args.before, args.after, args.protect)
    except ValueError as exc:
        p.error(str(exc))
    print(json.dumps(result, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# /// script
# requires-python = ">=3.11"
# ///
"""init_skill: scaffold a new skill folder, or check an existing one.

Create:
  init_skill.py --name <kebab> --dest <folder> --shape <shape> [--dirs references,scripts,assets]
                [--bmod <record-folder-name>] [--source <update_source>] [--description "..."]

  Shapes: plain-skill, script-utility, rendered-skill, rendered-agent, agent, memory-agent,
  single-skill-module, multi-skill-module. Writes <dest>/<name>/SKILL.md (frontmatter `name` and `description`, the given
  description or a [TODO: ...] placeholder, and an empty body heading), the requested dirs, and bmod.toml
  when --bmod is given or the shape is a module:
    - with --bmod: a [skill] table carrying `bmod` and `source`
    - single-skill-module: [bmod] with code (the name without its bmad- prefix), version = "0.1.0" and
      update_source, plus an empty [skill]
    - multi-skill-module: the module record, a bmod- folder with [bmod] only (code, version, update_source,
      skills = []) and the fixed record description
  Never writes module.yaml or a setup skill. Refuses a target folder that already exists.

Check:
  init_skill.py --check <skill-folder> [--any-name]

  Verifies SKILL.md exists, the frontmatter has only `name` and `description`, the name matches the folder
  and the bmad regex (bmod- for a module record; any kebab name with --any-name), the description is at
  most 1024 characters and contains "Use when" or "Use if" (a record carries the fixed text instead), the
  body is not empty, no `[TODO:` is left in any text file, and bmod.toml, when present, parses and carries
  [skill] or [bmod]. "bmod" in the output is absent, ok or invalid.

Output: one JSON object on stdout. Create: {"ok", "skill", "dir", "shape", "created": [...]}.
Check: {"ok", "skill", "bmod", "findings": [{"path", "line", "rule", "text", "fix"}, ...]}.
Exit 0 on success or a clean check, 1 on a failed check or a refused create, 2 on a usage error.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
import tomllib
from pathlib import Path

SHAPES = (
    "plain-skill",
    "script-utility",
    "rendered-skill",
    "rendered-agent",
    "agent",
    "memory-agent",
    "single-skill-module",
    "multi-skill-module",
)
KNOWN_DIRS = ("references", "scripts", "assets", "help", "evals")
KEBAB_RE = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
BMAD_NAME_RE = re.compile(r"^(?:bmad|bmad-[a-z0-9]+(?:-[a-z0-9]+)*)$")
RECORD_NAME_RE = re.compile(r"^bmod-[a-z0-9]+(?:-[a-z0-9]+)*$")
RECORD_DESCRIPTION = "Required bmod metadata. Never invoke this skill."
USE_WHEN_RE = re.compile(r"\buse\s+(?:when|if)\b", re.IGNORECASE)
TODO_RE = re.compile(r"\[TODO:")
TEXT_SUFFIXES = {".md", ".toml", ".py", ".json", ".yaml", ".yml", ".txt", ".html", ".csv"}
DESCRIPTION_PLACEHOLDER = "[TODO: five-to-eight-word summary. Use when the user says '<phrase>' or '<phrase>'.]"


def yaml_single_quoted(value: str) -> str:
    return "'" + value.replace("'", "''") + "'"


def toml_string(value: str) -> str:
    return json.dumps(value)


# --- frontmatter ---------------------------------------------------------------


def frontmatter_block(content: str) -> tuple[str | None, str]:
    """Return (frontmatter text or None, body)."""
    text = content.lstrip()
    if not text.startswith("---"):
        return None, content
    end = text.find("\n---", 3)
    if end == -1:
        return None, content
    after = text[end + 4 :]
    if after and not after.startswith(("\n", "\r")):
        return None, content
    return text[3:end].strip("\r\n"), after


def parse_frontmatter(content: str) -> tuple[dict[str, str] | None, str]:
    """Parse `key: value` frontmatter, folding indented continuation lines; return (dict or None, body)."""
    block, body = frontmatter_block(content)
    if block is None:
        return None, body
    result: dict[str, str] = {}
    key: str | None = None
    value = ""
    for line in block.split("\n"):
        colon = line.find(":")
        if colon > 0 and line[:1] not in (" ", "\t"):
            if key is not None:
                result[key] = strip_quotes(value.strip())
            key = line[:colon].strip()
            value = line[colon + 1 :]
        elif key is not None and not line.lstrip().startswith("#"):
            value += "\n" + line
    if key is not None:
        result[key] = strip_quotes(value.strip())
    return result, body


def strip_quotes(value: str) -> str:
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
        inner = value[1:-1]
        return inner.replace("''", "'") if value[0] == "'" else inner
    return value


# --- create --------------------------------------------------------------------


def skill_md(name: str, description: str) -> str:
    return f"---\nname: {name}\ndescription: {yaml_single_quoted(description)}\n---\n\n# {name}\n"


def bmod_toml(shape: str, name: str, bmod: str | None, source: str | None) -> str:
    source_value = toml_string(source) if source else toml_string("[TODO: update_source, e.g. github:org/repo/skills]")
    if shape == "multi-skill-module":
        code = name.removeprefix("bmod-")
        return f'[bmod]\ncode = {toml_string(code)}\nversion = "0.1.0"\nupdate_source = {source_value}\nskills = []\n'
    if shape == "single-skill-module":
        code = name.removeprefix("bmad-")
        return (
            f'[bmod]\ncode = {toml_string(code)}\nversion = "0.1.0"\nupdate_source = {source_value}\n\n'
            "# The record is in this same file, so the skill table needs no bmod or source.\n[skill]\n"
        )
    lines = ["[skill]"]
    if bmod:
        lines.append(f"bmod = {toml_string(bmod)}")
    if source:
        lines.append(f"source = {toml_string(source)}")
    return "\n".join(lines) + "\n"


def create(args) -> dict:
    name = args.name
    if not KEBAB_RE.match(name) or len(name) > 64:
        raise ValueError(f"name {name!r} must be kebab-case (lowercase, digits, single hyphens), at most 64 characters")
    if args.shape == "multi-skill-module" and not RECORD_NAME_RE.match(name):
        raise ValueError("a multi-skill-module record is named bmod-<code>")
    dirs = [d.strip() for d in (args.dirs or "").split(",") if d.strip()]
    unknown = [d for d in dirs if d not in KNOWN_DIRS]
    if unknown:
        raise ValueError(f"unknown dirs {', '.join(unknown)}; known: {', '.join(KNOWN_DIRS)}")
    skill_dir = Path(args.dest) / name
    if skill_dir.exists():
        raise FileExistsError(f"{skill_dir} already exists")

    description = args.description or DESCRIPTION_PLACEHOLDER
    if args.shape == "multi-skill-module":
        description = RECORD_DESCRIPTION

    skill_dir.mkdir(parents=True)
    created = []
    emitted = [("SKILL.md", skill_md(name, description))]
    if args.bmod or args.shape in ("single-skill-module", "multi-skill-module"):
        emitted.append(("bmod.toml", bmod_toml(args.shape, name, args.bmod, args.source)))
    for rel, text in emitted:
        (skill_dir / rel).write_text(text, encoding="utf-8")
        created.append(rel)
    for d in dirs:
        (skill_dir / d).mkdir()
        created.append(d + "/")
    return {"ok": True, "skill": name, "dir": str(skill_dir), "shape": args.shape, "created": created}


# --- check ---------------------------------------------------------------------


def finding(path: str, line: int, rule: str, text: str, fix: str) -> dict:
    return {"path": path, "line": line, "rule": rule, "text": text[:200], "fix": fix}


def read_bmod(skill_dir: Path, findings: list[dict]) -> tuple[dict | None, str]:
    """Return (parsed bmod.toml or None, status): status is absent, ok or invalid."""
    path = skill_dir / "bmod.toml"
    if not path.is_file():
        return None, "absent"
    try:
        data = tomllib.loads(path.read_text(encoding="utf-8"))
    except (tomllib.TOMLDecodeError, UnicodeDecodeError) as err:
        findings.append(finding("bmod.toml", 1, "bmod-invalid", str(err), "fix the TOML"))
        return None, "invalid"
    if "skill" not in data and "bmod" not in data:
        findings.append(finding("bmod.toml", 1, "bmod-tables", "neither [skill] nor [bmod]", "add a [skill] table"))
        return data, "invalid"
    return data, "ok"


def check(skill_dir: Path, any_name: bool) -> dict:
    findings: list[dict] = []
    bmod, bmod_status = read_bmod(skill_dir, findings)
    is_record = bool(bmod) and "bmod" in bmod and "skill" not in bmod

    skill_path = skill_dir / "SKILL.md"
    if not skill_path.is_file():
        findings.append(finding("SKILL.md", 1, "skill-md-missing", "no SKILL.md", "create SKILL.md"))
    else:
        content = skill_path.read_text(encoding="utf-8", errors="replace")
        meta, body = parse_frontmatter(content)
        if meta is None:
            findings.append(
                finding("SKILL.md", 1, "frontmatter-missing", content[:80], "open with --- name/description ---")
            )
        else:
            extra = sorted(set(meta) - {"name", "description"})
            if extra:
                findings.append(
                    finding("SKILL.md", 1, "frontmatter-keys", ", ".join(extra), "keep only name and description")
                )
            name = meta.get("name", "")
            if not name:
                findings.append(finding("SKILL.md", 1, "name-missing", "", "add name: <folder name>"))
            else:
                if name != skill_dir.name:
                    findings.append(
                        finding("SKILL.md", 2, "name-folder-mismatch", name, f"name must equal {skill_dir.name}")
                    )
                regex = KEBAB_RE if any_name else (RECORD_NAME_RE if is_record else BMAD_NAME_RE)
                if not regex.match(name):
                    findings.append(finding("SKILL.md", 2, "name-format", name, f"name must match {regex.pattern}"))
            desc = meta.get("description", "")
            if not desc:
                findings.append(
                    finding("SKILL.md", 1, "description-missing", "", "add a description with a Use when clause")
                )
            else:
                if len(desc) > 1024:
                    findings.append(
                        finding("SKILL.md", 3, "description-length", f"{len(desc)} chars", "cut to 1024 or fewer")
                    )
                if is_record:
                    if desc != RECORD_DESCRIPTION:
                        findings.append(
                            finding(
                                "SKILL.md",
                                3,
                                "description-trigger",
                                desc,
                                f"a record's description is {RECORD_DESCRIPTION!r}",
                            )
                        )
                elif not USE_WHEN_RE.search(desc):
                    findings.append(finding("SKILL.md", 3, "description-trigger", desc, 'add a "Use when ..." clause'))
            if not body.strip():
                findings.append(finding("SKILL.md", 1, "body-empty", "", "write the skill body after the frontmatter"))

    for path in sorted(skill_dir.rglob("*")):
        rel = path.relative_to(skill_dir)
        if not path.is_file() or path.suffix not in TEXT_SUFFIXES or any(p.startswith(".") for p in rel.parts):
            continue
        for number, line in enumerate(path.read_text(encoding="utf-8", errors="replace").splitlines(), 1):
            if TODO_RE.search(line):
                findings.append(
                    finding(rel.as_posix(), number, "todo-left", line.strip(), "fill in or remove the placeholder")
                )

    return {"ok": not findings, "skill": skill_dir.name, "bmod": bmod_status, "findings": findings}


# --- cli -----------------------------------------------------------------------


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--check", type=Path, metavar="SKILL", help="check this skill folder instead of creating one")
    p.add_argument("--any-name", action="store_true", help="with --check: accept any kebab-case name")
    p.add_argument("--name", help="skill name, kebab-case")
    p.add_argument("--dest", type=Path, help="parent folder the skill folder is created under")
    p.add_argument("--shape", choices=SHAPES, help="skill shape")
    p.add_argument("--dirs", default="", help=f"comma-separated folders to create: {', '.join(KNOWN_DIRS)}")
    p.add_argument("--bmod", help="record folder name for the [skill] table, e.g. bmod-method")
    p.add_argument("--source", help="update_source for the [skill] or [bmod] table")
    p.add_argument("--description", help="frontmatter description; a [TODO: ...] placeholder when omitted")
    args = p.parse_args(argv)

    if args.check:
        if not args.check.is_dir():
            p.error(f"not a directory: {args.check}")
        result = check(args.check, args.any_name)
        print(json.dumps(result, indent=2))
        return 0 if result["ok"] else 1

    if not (args.name and args.dest and args.shape):
        p.error("--name, --dest and --shape are required to create a skill (or use --check)")
    try:
        result = create(args)
    except (ValueError, FileExistsError) as err:
        print(json.dumps({"ok": False, "error": str(err)}))
        return 1
    print(json.dumps(result, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# /// script
# requires-python = ">=3.11"
# ///
"""read_session_log: digest Claude Code transcripts and memlogs into a compact JSON for the from-logs approach.

Sources:
  claude-code   a session transcript, one JSON object per line, as Claude Code keeps them under
                ~/.claude/projects/<encoded-cwd>/*.jsonl (the cwd with every "/" and "." turned into "-";
                $CLAUDE_CONFIG_DIR replaces ~/.claude when set). Read: user prompts, tool calls per turn,
                `Skill` tool calls and /command invocations, files named in tool inputs. Meta and sidechain
                (subagent) records are skipped. Tool results and assistant prose are never copied out.
  memlog        a .memlog.md: entries typed direction or decision, or marked `by user`, count as requests;
                entries typed gap or correction, or reading like a correction, count as corrections.

A correction is a user message that opens with a word of refusal or redirection (no, don't, stop, wrong,
wait, actually, instead, undo, revert, ...) or a request interrupted by the user. It is a heuristic; read the
digest as leads, not verdicts.

Usage:
  read_session_log.py [<path> ...] [--project <cwd>] [--format auto|claude-code|memlog] [--max-items N]

  A path may be a file or a folder (every *.jsonl and *.memlog.md inside). --project resolves the
  transcript folder for that working directory. --format auto picks by file name.

Output, one JSON object on stdout; every text is cut to 300 characters and every list to --max-items:
  {"sources": [{"path", "format", "entries"}], "user_requests": [{"text", "count"}],
   "tool_sequences": [{"tools": [...], "count"}], "corrections": [text, ...],
   "files_touched": [path, ...], "skills_invoked": [{"name", "count"}]}
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys
from collections import Counter
from pathlib import Path

TEXT_LIMIT = 300
CORRECTION_RE = re.compile(
    r"^(?:no|nope|not|don'?t|do not|stop|wrong|wait|actually|instead|undo|revert|never|hold on|"
    r"that'?s (?:not|wrong)|that is (?:not|wrong)|why did you|i said|i asked|not what)\b",
    re.IGNORECASE,
)
INTERRUPTED_RE = re.compile(r"^\[Request interrupted by user")
COMMAND_RE = re.compile(r"<command-name>\s*/?([^<\s]+)\s*</command-name>")
MEMLOG_ENTRY_RE = re.compile(r"^- (?:\((?P<tag>[^)]*)\) )?(?P<text>.*)$")
FILE_INPUT_KEYS = ("file_path", "notebook_path", "path")


def truncate(text: str) -> str:
    text = " ".join(text.split())
    return text if len(text) <= TEXT_LIMIT else text[: TEXT_LIMIT - 3] + "..."


def encode_cwd(cwd: str) -> str:
    return re.sub(r"[/.]", "-", cwd)


def projects_dir() -> Path:
    base = os.environ.get("CLAUDE_CONFIG_DIR")
    return (Path(base) if base else Path.home() / ".claude") / "projects"


class Digest:
    def __init__(self) -> None:
        self.sources: list[dict] = []
        self.requests: Counter[str] = Counter()
        self.request_text: dict[str, str] = {}
        self.sequences: Counter[tuple[str, ...]] = Counter()
        self.corrections: list[str] = []
        self.files: set[str] = set()
        self.skills: Counter[str] = Counter()

    def add_request(self, text: str) -> None:
        key = " ".join(text.lower().split())
        if not key:
            return
        self.requests[key] += 1
        self.request_text.setdefault(key, truncate(text))
        if CORRECTION_RE.match(text.strip()) or INTERRUPTED_RE.match(text.strip()):
            self.add_correction(text)

    def add_correction(self, text: str) -> None:
        short = truncate(text)
        if short not in self.corrections:
            self.corrections.append(short)

    def add_sequence(self, tools: list[str]) -> None:
        collapsed: list[str] = []
        for tool in tools:
            if not collapsed or collapsed[-1] != tool:
                collapsed.append(tool)
        if collapsed:
            self.sequences[tuple(collapsed)] += 1

    def render(self, max_items: int) -> dict:
        return {
            "sources": self.sources,
            "user_requests": [
                {"text": self.request_text[key], "count": count} for key, count in self.requests.most_common(max_items)
            ],
            "tool_sequences": [
                {"tools": list(seq), "count": count} for seq, count in self.sequences.most_common(max_items)
            ],
            "corrections": self.corrections[:max_items],
            "files_touched": sorted(self.files)[:max_items],
            "skills_invoked": [{"name": name, "count": count} for name, count in self.skills.most_common(max_items)],
        }


def user_text(content) -> str | None:
    """Return the prompt text of a user record, or None when it is only tool results."""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        texts = [b.get("text", "") for b in content if isinstance(b, dict) and b.get("type") == "text"]
        return "\n".join(t for t in texts if t) if texts else None
    return None


def read_claude_code(path: Path, digest: Digest) -> int:
    entries = 0
    turn_tools: list[str] = []
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue
        if not isinstance(record, dict) or record.get("isMeta") or record.get("isSidechain"):
            continue
        message = record.get("message") if isinstance(record.get("message"), dict) else None
        if message is None:
            continue
        content = message.get("content")
        kind = record.get("type")
        if kind == "user":
            text = user_text(content)
            if text is None:
                continue
            entries += 1
            digest.add_sequence(turn_tools)
            turn_tools = []
            for command in COMMAND_RE.findall(text):
                digest.skills[command] += 1
            stripped = text.strip()
            if INTERRUPTED_RE.match(stripped):
                digest.add_correction(stripped)
            elif stripped and not stripped.startswith("<"):
                digest.add_request(stripped)
        elif kind == "assistant" and isinstance(content, list):
            for block in content:
                if not isinstance(block, dict) or block.get("type") != "tool_use":
                    continue
                entries += 1
                name = str(block.get("name", ""))
                turn_tools.append(name)
                inputs = block.get("input") if isinstance(block.get("input"), dict) else {}
                if name == "Skill" and inputs.get("skill"):
                    digest.skills[str(inputs["skill"])] += 1
                for key in FILE_INPUT_KEYS:
                    if isinstance(inputs.get(key), str) and inputs[key]:
                        digest.files.add(inputs[key])
    digest.add_sequence(turn_tools)
    return entries


def read_memlog(path: Path, digest: Digest) -> int:
    entries = 0
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        match = MEMLOG_ENTRY_RE.match(line)
        if not match:
            continue
        entries += 1
        tag = (match.group("tag") or "").strip().lower()
        kind = tag.split(" by ")[0].strip()
        by_user = " by user" in f" {tag}" or tag.startswith("by user")
        text = match.group("text").strip()
        if kind in ("gap", "correction"):
            digest.add_correction(text)
        elif kind in ("direction", "decision") or by_user:
            digest.add_request(text)
        elif CORRECTION_RE.match(text):
            digest.add_correction(text)
    return entries


def detect_format(path: Path, requested: str) -> str | None:
    if requested != "auto":
        return requested
    if path.suffix == ".jsonl":
        return "claude-code"
    if path.name.endswith(".memlog.md") or path.name == ".memlog.md":
        return "memlog"
    return None


def expand(paths: list[Path]) -> list[Path]:
    files: list[Path] = []
    for path in paths:
        if path.is_dir():
            files.extend(sorted(path.glob("*.jsonl"), key=lambda p: p.stat().st_mtime))
            files.extend(sorted(path.glob("*.memlog.md")))
        else:
            files.append(path)
    return files


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("paths", nargs="*", type=Path, help="transcript files, memlogs, or folders of them")
    p.add_argument("--project", help="working directory whose Claude Code transcripts to read")
    p.add_argument("--format", choices=("auto", "claude-code", "memlog"), default="auto")
    p.add_argument("--max-items", type=int, default=20, help="cap for every list (default 20)")
    args = p.parse_args(argv)

    paths = list(args.paths)
    if args.project:
        folder = projects_dir() / encode_cwd(str(Path(args.project).expanduser().resolve()))
        if not folder.is_dir():
            p.error(f"no transcripts for {args.project} at {folder}")
        paths.append(folder)
    if not paths:
        p.error("give at least one path or --project")
    missing = [str(path) for path in paths if not path.exists()]
    if missing:
        p.error(f"not found: {', '.join(missing)}")

    digest = Digest()
    for path in expand(paths):
        fmt = detect_format(path, args.format)
        if fmt is None:
            print(f"read_session_log: skipping {path}, unknown format", file=sys.stderr)
            continue
        reader = read_claude_code if fmt == "claude-code" else read_memlog
        entries = reader(path, digest)
        digest.sources.append({"path": str(path), "format": fmt, "entries": entries})

    print(json.dumps(digest.render(args.max_items), indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# /// script
# requires-python = ">=3.11"
# dependencies = ["pyyaml>=6.0.2,<7"]
# ///
"""scan_legacy_module: parse an old-format BMad module so the migrate mode can convert it.

The old format described a module with a `module.yaml` (code, module_version, module_greeting, an optional
`agents` roster, and one block per config key with `prompt`, `default`, `result`, `user_setting`,
`single-select` or `multi-select`), a `module-help.csv` registry, and a `<code>-setup` skill (or an
`assets/module-setup.md` in a single-skill module) that merged both into `_bmad/config.yaml`,
`config.user.yaml` and `module-help.csv` with merge scripts. bmod.toml replaces all of it.

Usage:
  scan_legacy_module.py <module-folder>

Output, one JSON object on stdout; paths are relative to the module folder:
  {"module": {"code", "name", "version", "greeting", "agents": [...]},
   "config_keys": [{"key", "prompt", "default", "user_setting", "kind", "unconvertible": [...]}],
   "help_rows": [{"skill", ...the other CSV columns}],
   "skills": [folder names that hold a SKILL.md],
   "legacy_reads": [{"skill", "path", "line", "text"}],
   "setup_skill": name or null,
   "files_to_delete": [...]}

kind is text, single-select, multi-select or confirm. unconvertible lists what a bmod [[bmod.config_questions]]
entry (key, prompt, default, scope) cannot carry: select options, a result template, regex, required, example,
a boolean default. legacy_reads lists every line in a skill that reads _bmad/config.yaml, config.user.yaml,
_bmad/<code>/config.yaml or names a bmad-*-setup skill, outside the files slated for deletion.
Exit 0 on success, 1 when no module.yaml is found, 2 on a usage error.
"""

from __future__ import annotations

import argparse
import csv
import json
import re
import sys
from pathlib import Path

import yaml

SKIP_DIRS = {".git", "__pycache__", "node_modules", ".venv", "venv", ".pytest_cache"}
MODULE_META_KEYS = {
    "code",
    "name",
    "header",
    "subheader",
    "description",
    "module_version",
    "default_selected",
    "module_greeting",
    "agents",
    "directories",
    "post-install-notes",
}
LEGACY_FILE_NAMES = {"module.yaml", "module-help.csv", "merge-config.py", "merge-help-csv.py", "cleanup-legacy.py"}
LEGACY_READ_RE = re.compile(r"_bmad/config\.yaml|config\.user\.yaml|\bbmad-[a-z0-9-]+-setup\b|module-setup\.md")


def walk(root: Path):
    for path in sorted(root.rglob("*")):
        if path.is_file() and not any(part in SKIP_DIRS for part in path.relative_to(root).parts):
            yield path


def find_one(root: Path, name: str) -> Path | None:
    """The shallowest file with this name, or None."""
    matches = sorted((p for p in walk(root) if p.name == name), key=lambda p: (len(p.parts), str(p)))
    return matches[0] if matches else None


def rel(root: Path, path: Path) -> str:
    return path.relative_to(root).as_posix()


def load_module_yaml(path: Path) -> dict:
    data = yaml.safe_load(path.read_text(encoding="utf-8"))
    return data if isinstance(data, dict) else {}


def config_key(key: str, spec: dict) -> dict:
    reasons = []
    kind = "text"
    if "single-select" in spec:
        kind = "single-select"
        reasons.append("single-select options; ask as free text and name the choices in the prompt")
    elif "multi-select" in spec:
        kind = "multi-select"
        reasons.append("multi-select options; a bmod answer is one scalar")
    elif isinstance(spec.get("default"), bool):
        kind = "confirm"
        reasons.append("boolean default; store the answer as a string or drop the question")
    result = spec.get("result")
    if isinstance(result, str) and result not in ("{value}", ""):
        reasons.append(f"result template {result!r}; fold it into the default and the skill that reads it")
    for extra in ("regex", "required", "example"):
        if extra in spec:
            reasons.append(f"{extra} has no bmod equivalent")
    return {
        "key": key,
        "prompt": spec.get("prompt", ""),
        "default": spec.get("default"),
        "user_setting": spec.get("user_setting") is True,
        "kind": kind,
        "unconvertible": reasons,
    }


def read_help_rows(path: Path | None) -> list[dict]:
    if path is None:
        return []
    with path.open(encoding="utf-8", newline="") as handle:
        rows = list(csv.DictReader(handle))
    return [
        {"skill": row.get("skill", ""), **{k: v for k, v in row.items() if k != "skill" and k is not None}}
        for row in rows
    ]


def skill_dirs(root: Path) -> list[Path]:
    return sorted({p.parent for p in walk(root) if p.name == "SKILL.md"})


def skill_of(root: Path, path: Path, skills: list[Path]) -> str:
    for skill in sorted(skills, key=lambda p: -len(p.parts)):
        if skill == path.parent or skill in path.parents:
            return skill.name
    return root.name


def scan(root: Path) -> dict | None:
    module_yaml = find_one(root, "module.yaml")
    if module_yaml is None:
        return None
    meta = load_module_yaml(module_yaml)
    help_csv = find_one(root, "module-help.csv")
    skills = skill_dirs(root)

    setup_skill = next((s.name for s in skills if s.name.endswith("-setup")), None)
    module_setup = find_one(root, "module-setup.md")

    to_delete: set[str] = set()
    for path in walk(root):
        if path.name in LEGACY_FILE_NAMES:
            to_delete.add(rel(root, path))
    if setup_skill:
        setup_dir = next(s for s in skills if s.name == setup_skill)
        to_delete = {p for p in to_delete if not p.startswith(rel(root, setup_dir) + "/")}
        to_delete.add(rel(root, setup_dir) + "/")
    if module_setup is not None:
        to_delete.add(rel(root, module_setup))

    reads = []
    for path in walk(root):
        if path.suffix != ".md":
            continue
        relative = rel(root, path)
        if relative in to_delete or any(relative.startswith(d) for d in to_delete if d.endswith("/")):
            continue
        for number, line in enumerate(path.read_text(encoding="utf-8", errors="replace").splitlines(), 1):
            if LEGACY_READ_RE.search(line):
                reads.append(
                    {
                        "skill": skill_of(root, path, skills),
                        "path": relative,
                        "line": number,
                        "text": line.strip()[:200],
                    }
                )

    greeting = meta.get("module_greeting", "")
    return {
        "module": {
            "code": meta.get("code", ""),
            "name": meta.get("name", ""),
            "version": str(meta.get("module_version", "")),
            "greeting": greeting.strip() if isinstance(greeting, str) else "",
            "agents": meta.get("agents") if isinstance(meta.get("agents"), list) else [],
        },
        "config_keys": [
            config_key(k, v)
            for k, v in meta.items()
            if k not in MODULE_META_KEYS and isinstance(v, dict) and "prompt" in v
        ],
        "help_rows": read_help_rows(help_csv),
        "skills": [s.name for s in skills if s.name != setup_skill],
        "legacy_reads": reads,
        "setup_skill": setup_skill,
        "files_to_delete": sorted(to_delete),
    }


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("module", type=Path, help="old-format module folder")
    args = p.parse_args(argv)
    if not args.module.is_dir():
        p.error(f"not a directory: {args.module}")
    result = scan(args.module)
    if result is None:
        print(f"scan_legacy_module: no module.yaml under {args.module}", file=sys.stderr)
        return 1
    print(json.dumps(result, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())

